"""Author 61: turn the ASCII transliteration of German decisions into real umlauts (word list), for the file given as argument."""
import json, sys
W = [("spindelfoermiger","spindelförmiger"),("Kronenfuellung","Kronenfüllung"),("Anfaengen","Anfängen"),("Aeste","Äste"),("Aesten","Ästen"),("Wuelste","Wülste"),("Wuelsten","Wülsten"),("Fuellung","Füllung"),("Fuellungs","Füllungs"),("fuenf","fünf"),("ueber","über"),("Roehren","Röhren"),("Roehre","Röhre"),("Hoehe","Höhe"),("Koerpersilhouette","Körpersilhouette"),("Massstab","Maßstab"),("unveraendert","unverändert"),("Kegelstuempfe","Kegelstümpfe"),("Kegelstumpf","Kegelstumpf"),("duenne","dünne"),("duennen","dünnen"),("Vorhaenge","Vorhänge"),("Aussenaeste","Außenäste"),("ergaenzt","ergänzt"),("ergaenzen","ergänzen"),("Anlaeufe","Anläufe"),("verallgemeinert","verallgemeinert"),("waere","wäre"),("fuer","für"),("Fuer","Für"),("Grundriss-Fussabdruck","Grundriss-Fußabdruck"),("Fussabdruck","Fußabdruck"),("Aestchen","Ästchen"),("moeglich","möglich"),("verschmaelert","verschmälert"),("Naehe","Nähe"),("laeuft","läuft"),("Blaetter","Blätter"),("Blaettern","Blättern"),("Zweige","Zweige"),("grosse","große"),("gross","groß"),("Groesse","Größe"),("Raender","Ränder"),("Rand","Rand"),("Maessig","Mäßig"),("Ueberlapp","Überlapp"),("Ueberlag","Überlag"),("gewoelbt","gewölbt"),("Woelbung","Wölbung"),("koennen","können"),("muessen","müssen"),("Kruemm","Krümm"),("gekruemmt","gekrümmt"),("Verzweigung","Verzweigung"),("vollstaendig","vollständig"),("staendig","ständig"),("Staemme","Stämme"),("Staemmen","Stämmen"),("hoeher","höher"),("tiefer","tiefer"),("Schaetzung","Schätzung"),("Flaeche","Fläche"),("Flaechen","Flächen"),("flaechig","flächig"),("Abstaende","Abstände"),("Haelfte","Hälfte"),("gehoert","gehört"),("Bueschel","Büschel"),("Buendel","Bündel"),("Spitzen","Spitzen"),("duenn","dünn"),("Oeffnung","Öffnung"),("oeffnen","öffnen"),("Hoehen","Höhen"),("Schaefte","Schäfte"),("Haelmchen","Hälmchen"),("Halme","Halme"),("Rispen","Rispen"),("Baeume","Bäume"),("Baum","Baum"),("Kronenansaetze","Kronenansätze"),("Stuetz","Stütz"),("Traeger","Träger"),("tragende","tragende"),("Querschnitte","Querschnitte"),("zusaetzlich","zusätzlich"),("Ausmass","Ausmaß"),("Gewaechs","Gewächs"),("laenger","länger"),("kuerzer","kürzer"),("Laenge","Länge"),("Laengen","Längen"),("Breite","Breite"),("uebernommen","übernommen"),("uebrig","übrig"),("Uebergang","Übergang"),("natuerlich","natürlich"),("Natuerlich","Natürlich"),("Rueckseite","Rückseite"),("Rueck","Rück"),("Zurueck","Zurück"),("zurueck","zurück"),("Glaettung","Glättung"),("Gelaender","Geländer"),("Daempfung","Dämpfung"),("Waerme","Wärme"),("Waermekapazitaet","Wärmekapazität"),("Koerper","Körper"),("Koerpers","Körpers"),("Kontaktflaeche","Kontaktfläche"),("Austauschflaeche","Austauschfläche"),("Bodenflaeche","Bodenfläche"),("Gesamtflaeche","Gesamtfläche"),("Auflageplatte","Auflageplatte"),("Grundrisse","Grundrisse"),("Kegelstumpf-Stapel","Kegelstumpf-Stapel"),("Massen","Massen")]
f = sys.argv[1]
d = json.load(open(f))
n = 0
for sc in d["volumes"].values():
    if sc.get("status") != "authored": continue
    for dec in sc["decisions"]:
        t = dec["de"]
        for a, b in W: t = t.replace(a, b)
        if t != dec["de"]: n += 1; dec["de"] = t
json.dump(d, open(f, "w"), indent=1, ensure_ascii=False)
open(f, "a").write("\n")
print(f, n, "German lines changed")
